	"disposition" text,
	"evidence" text,
	"delivered_at" timestamp with time zone,
	"acknowledged_at" timestamp with time zone,
	CONSTRAINT "review_file_evidence_review_path_unique" UNIQUE("review_id","path"),
	CONSTRAINT "review_file_evidence_disposition_check" CHECK ((disposition IS NULL) OR (disposition = ANY (ARRAY['reviewed'::text, 'blocked'::text]))),
	CONSTRAINT "review_file_evidence_ack_shape_check" CHECK ((disposition IS NULL AND evidence IS NULL AND acknowledged_at IS NULL) OR
